#include "transmissionwidget.h"
#include <QPainter>
#include <QTimer>
TransmissionWidget::TransmissionWidget(QWidget *p):QWidget(p){setMinimumHeight(118);m_timer=new QTimer(this);m_timer->setInterval(32);connect(m_timer,&QTimer::timeout,this,[this]{m_phase+=.018;if(m_phase>1)m_phase=0;update();});}
void TransmissionWidget::start(bool d,const QString&a){m_decrypting=d;m_algorithm=a;m_running=true;m_success=false;m_phase=0;m_timer->start();update();}
void TransmissionWidget::finish(bool ok){m_timer->stop();m_running=false;m_success=ok;m_phase=1;update();}
void TransmissionWidget::paintEvent(QPaintEvent*){QPainter p(this);p.setRenderHint(QPainter::Antialiasing);QRectF r=rect().adjusted(12,12,-12,-12);p.setPen(QPen(QColor("#52647b"),2));p.drawLine(QPointF(r.left()+105,r.center().y()),QPointF(r.right()-105,r.center().y()));QStringList labels=m_decrypting?QStringList{"Tệp mã hóa","Giải mã","Nội dung gốc"}:QStringList{"Tệp gốc",m_algorithm,"Dữ liệu truyền"};QList<qreal> xs{r.left()+70,r.center().x(),r.right()-70};for(int i=0;i<3;i++){QRectF box(xs[i]-68,r.center().y()-32,136,64);p.setBrush(i==1?QColor("#24364d"):QColor("#1b2636"));p.setPen(QPen(i==1?QColor("#54a6ff"):QColor("#52647b")));p.drawRoundedRect(box,8,8);p.setPen(Qt::white);p.drawText(box,Qt::AlignCenter,labels[i]);}if(m_running){qreal x=r.left()+105+(r.width()-210)*m_phase;p.setBrush(QColor("#55d98b"));p.setPen(Qt::NoPen);p.drawEllipse(QPointF(x,r.center().y()),7,7);}if(m_success){p.setPen(QColor("#55d98b"));p.drawText(QRectF(r.left(),r.bottom()-16,r.width(),20),Qt::AlignCenter,"Truyền và xác thực dữ liệu thành công");}}
